import { supabase } from '../supabaseClient';
import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval, PharmaCompany, HospitalUser, AuthUser } from '../types';

const SESSION_KEY = 'medpass_session';

export const storageService = {
  // --- AUTH & SESSION ---
  setCurrentUser: (user: AuthUser) => localStorage.setItem(SESSION_KEY, JSON.stringify(user)),
  getCurrentUser: (): AuthUser | null => {
    const session = localStorage.getItem(SESSION_KEY);
    return session ? JSON.parse(session) : null;
  },
  clearSession: () => localStorage.removeItem(SESSION_KEY),

  // --- MRs ---
  getMRs: async (): Promise<MedicalRep[]> => {
    const { data, error } = await supabase
      .from('mrs')
      .select(`
        id, 
        mr_code, 
        mobile_number, 
        identification_number, 
        slcpi_id, 
        slcpi_photo, 
        slcpi_expiry, 
        status, 
        created_at,
        pharma_companies (name)
      `);
    if (error) throw error;
    return (data || []).map(m => ({
      id: m.id,
      fullName: '', // Note: Full name is usually in profiles
      companyName: (m.pharma_companies as any)?.name || '',
      mrId: m.mr_code,
      loginId: m.mobile_number, // Mapping loginId to mobile for simplicity
      mobileNumber: m.mobile_number,
      identificationNumber: m.identification_number,
      slcpiId: m.slcpi_id,
      slcpiPhoto: m.slcpi_photo,
      slcpiExpiry: m.slcpi_expiry,
      status: m.status as any,
      createdAt: m.created_at
    }));
  },

  // --- HOSPITALS ---
  getHospitals: async (): Promise<Hospital[]> => {
    const { data, error } = await supabase.from('hospitals').select('*');
    if (error) throw error;
    return (data || []).map(h => ({
      id: h.id,
      name: h.name,
      address: h.address,
      email: h.email,
      mobileNumber: h.mobile_number,
      isActive: h.is_active,
      supportedSessions: h.supported_sessions,
      passLimits: h.pass_limits,
      sessionWindows: h.session_windows
    }));
  },

  saveHospitals: async (hospitals: Hospital[]) => {
    // This helper saves/updates hospitals. In a real app we'd target specific IDs.
    for (const h of hospitals) {
      const { error } = await supabase.from('hospitals').upsert({
        id: h.id,
        name: h.name,
        address: h.address,
        email: h.email,
        mobile_number: h.mobileNumber,
        is_active: h.isActive,
        supported_sessions: h.supportedSessions,
        pass_limits: h.passLimits,
        session_windows: h.sessionWindows
      });
      if (error) console.error(error);
    }
  },

  // --- APPLICATIONS ---
  getApplications: async (): Promise<PassApplication[]> => {
    const { data, error } = await supabase.from('applications').select('*');
    if (error) throw error;
    return (data || []).map(a => ({
      id: a.id,
      mrId: a.mr_id,
      hospitalId: a.hospital_id,
      session: a.session,
      applicationDate: a.application_date,
      priorityScore: a.priority_score,
      status: a.status,
      createdAt: a.created_at
    }));
  },

  saveApplications: async (apps: PassApplication[]) => {
    for (const a of apps) {
      const { error } = await supabase.from('applications').upsert({
        id: a.id,
        mr_id: a.mrId,
        hospital_id: a.hospitalId,
        session: a.session,
        application_date: a.applicationDate,
        priority_score: a.priorityScore,
        status: a.status
      });
      if (error) console.error(error);
    }
  },

  // --- PASSES ---
  getPasses: async (): Promise<IssuedPass[]> => {
    const { data, error } = await supabase.from('passes').select('*');
    if (error) throw error;
    return (data || []).map(p => ({
      id: p.id,
      mrId: p.mr_id,
      hospitalId: p.hospital_id,
      session: p.session,
      passDate: p.pass_date,
      timeSlot: p.time_slot,
      qrCode: p.qr_code,
      entryStatus: p.entry_status
    }));
  },

  savePasses: async (passes: IssuedPass[]) => {
    for (const p of passes) {
      const { error } = await supabase.from('passes').upsert({
        id: p.id,
        mr_id: p.mrId,
        hospital_id: p.hospitalId,
        session: p.session,
        pass_date: p.passDate,
        time_slot: p.timeSlot,
        qr_code: p.qrCode,
        entry_status: p.entryStatus
      });
      if (error) console.error(error);
    }
  },

  // --- COMPANIES ---
  getCompanies: async (): Promise<PharmaCompany[]> => {
    const { data, error } = await supabase.from('pharma_companies').select('*');
    if (error) throw error;
    return (data || []).map(c => ({
      id: c.id,
      name: c.name,
      companyCode: c.company_code,
      address: c.address,
      contactNumber: c.contact_number,
      financeEmail: c.finance_email,
      contactEmail: c.contact_email,
      isActive: c.is_active,
      // For demo, passwords aren't in this table but we can mock or use profiles
      adminMobile: '', 
      adminPassword: ''
    }));
  },

  // --- PROFILES & AUTH HELPER ---
  getProfileByCredentials: async (mobile: string, pass: string, role: string) => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('mobile_number', mobile)
      .eq('password', pass)
      .eq('role', role)
      .single();
    if (error) return null;
    return data;
  },

  getLogs: async (): Promise<EntryLog[]> => {
    const { data, error } = await supabase.from('entry_logs').select('*');
    if (error) throw error;
    return (data || []).map(l => ({
      id: l.id,
      issuedPassId: l.pass_id,
      entryTime: l.entry_time,
      verifiedBy: l.verified_by
