import { supabase } from '../supabaseClient';
import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval, PharmaCompany, HospitalUser, AuthUser } from '../types';

const SESSION_KEY = 'medpass_session';

export const storageService = {
  // --- AUTH & SESSION ---
  setCurrentUser: (user: AuthUser) => localStorage.setItem(SESSION_KEY, JSON.stringify(user)),
  getCurrentUser: (): AuthUser | null => {
    const session = localStorage.getItem(SESSION_KEY);
    return session ? JSON.parse(session) : null;
  },
  clearSession: () => localStorage.removeItem(SESSION_KEY),

  // --- MRs ---
  getMRs: async (): Promise<MedicalRep[]> => {
    // Note: To get the full name, we join with the profiles table which shares the same ID
    const { data, error } = await supabase
      .from('mrs')
      .select(`
        id, 
        mr_code, 
        mobile_number, 
        identification_number, 
        slcpi_id, 
        slcpi_photo, 
        slcpi_expiry, 
        status, 
        created_at,
        pharma_companies (name)
      `);

    if (error) throw error;

    // Fetch names from profiles separately if not joined easily due to foreign key constraints
    const { data: profiles } = await supabase.from('profiles').select('id, full_name').eq('role', 'MR');
    const profileMap = new Map((profiles || []).map(p => [p.id, p.full_name]));

    return (data || []).map(m => ({
      id: m.id,
      fullName: profileMap.get(m.id) || '',
      companyName: (m.pharma_companies as any)?.name || '',
      mrId: m.mr_code,
      loginId: m.mobile_number,
      mobileNumber: m.mobile_number,
      identificationNumber: m.identification_number,
      slcpiId: m.slcpi_id,
      slcpiPhoto: m.slcpi_photo,
      slcpiExpiry: m.slcpi_expiry,
      status: m.status as any,
      createdAt: m.created_at
    }));
  },

  saveMRs: async (mrs: MedicalRep[]) => {
    for (const mr of mrs) {
      // First update the profile for the name
      await supabase.from('profiles').upsert({
        id: mr.id,
        full_name: mr.fullName,
        role: 'MR',
        mobile_number: mr.mobileNumber
      });

      // Then update the MR specific data
      const { error } = await supabase.from('mrs').upsert({
        id: mr.id,
        mr_code: mr.mrId,
        mobile_number: mr.mobileNumber,
        identification_number: mr.identificationNumber,
        slcpi_id: mr.slcpiId,
        slcpi_photo: mr.slcpiPhoto,
        slcpi_expiry: mr.slcpiExpiry,
        status: mr.status
      });
      if (error) console.error(error);
    }
  },

  // --- HOSPITALS ---
  getHospitals: async (): Promise<Hospital[]> => {
    const { data, error } = await supabase.from('hospitals').select('*');
    if (error) throw error;
    return (data || []).map(h => ({
      id: h.id,
      name: h.name,
      address: h.address,
      email: h.email,
      mobileNumber: h.mobile_number,
      isActive: h.is_active,
      supportedSessions: h.supported_sessions,
      passLimits: h.pass_limits,
      sessionWindows: h.session_windows
    }));
  },

  saveHospitals: async (hospitals: Hospital[]) => {
    for (const h of hospitals) {
      const { error } = await supabase.from('hospitals').upsert({
        id: h.id,
        name: h.name,
        address: h.address,
        email: h.email,
        mobile_number: h.mobileNumber,
        is_active: h.isActive,
        supported_sessions: h.supportedSessions,
        pass_limits: h.passLimits,
        session_windows: h.sessionWindows
      });
      if (error) console.error(error);
    }
  },

  // Fix: Redirected from hospital_users to profiles table
  getHospitalUsers: async (): Promise<HospitalUser[]> => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .in('role', ['HOSPITAL_ADMIN', 'SECURITY']);
    if (error) throw error;
    return (data || []).map(u => ({
      id: u.id,
      hospitalId: u.hospital_id,
      mobileNumber: u.mobile_number,
      password: u.password,
      role: u.role === 'HOSPITAL_ADMIN' ? 'ADMIN' : u.role,
      fullName: u.full_name
    }));
  },

  // Fix: Redirected from hospital_users to profiles table
  saveHospitalUsers: async (users: HospitalUser[]) => {
    for (const u of users) {
      const { error } = await supabase.from('profiles').upsert({
        id: u.id,
        hospital_id: u.hospitalId,
        mobile_number: u.mobileNumber,
        password: u.password,
        role: u.role === 'ADMIN' ? 'HOSPITAL_ADMIN' : u.role,
        full_name: u.fullName
      });
      if (error) console.error(error);
    }
  },

  // --- APPLICATIONS ---
  getApplications: async (): Promise<PassApplication[]> => {
    const { data, error } = await supabase.from('applications').select('*');
    if (error) throw error;
    return (data || []).map(a => ({
      id: a.id,
      mrId: a.mr_id,
      hospitalId: a.hospital_id,
      session: a.session,
      applicationDate: a.application_date,
      priorityScore: a.priority_score,
      status: a.status,
      createdAt: a.created_at
    }));
  },

  saveApplications: async (apps: PassApplication[]) => {
    for (const a of apps) {
      const { error } = await supabase.from('applications').upsert({
        id: a.id,
        mr_id: a.mrId,
        hospital_id: a.hospitalId,
        session: a.session,
        application_date: a.applicationDate,
        priority_score: a.priorityScore,
        status: a.status
      });
      if (error) console.error(error);
    }
  },

  // --- PASSES ---
  getPasses: async (): Promise<IssuedPass[]> => {
    const { data, error } = await supabase.from('passes').select('*');
    if (error) throw error;
    return (data || []).map(p => ({
      id: p.id,
      mrId: p.mr_id,
      hospitalId: p.hospital_id,
      session: p.session,
      passDate: p.pass_date,
      timeSlot: p.time_slot,
      qrCode: p.qr_code,
      entryStatus: p.entry_status
    }));
  },

  savePasses: async (passes: IssuedPass[]) => {
    for (const p of passes) {
      const { error } = await supabase.from('passes').upsert({
        id: p.id,
        mr_id: p.mrId,
        hospital_id: p.hospitalId,
        session: p.session,
        pass_date: p.pass_date,
        time_slot: p.timeSlot,
        qr_code: p.qrCode,
        entry_status: p.entryStatus
      });
      if (error) console.error(error);
    }
  },

  // --- COMPANIES ---
  getCompanies: async (): Promise<PharmaCompany[]> => {
    const { data, error } = await supabase.from('pharma_companies').select('*');
    if (error) throw error;
    return (data || []).map(c => ({
      id: c.id,
      name: c.name,
      companyCode: c.company_code,
      address: c.address,
      contactNumber: c.contact_number,
      financeEmail: c.finance_email,
      contactEmail: c.contact_email,
      isActive: c.is_active,
      adminMobile: '', 
      adminPassword: ''
    }));
  },

  saveCompanies: async (companies: PharmaCompany[]) => {
    for (const c of companies) {
      const { error } = await supabase.from('pharma_companies').upsert({
        id: c.id,
        name: c.name,
        company_code: c.companyCode,
        address: c.address,
        contact_number: c.contactNumber,
        finance_email: c.financeEmail,
        contact_email: c.contactEmail,
        is_active: c.isActive
      });
      if (error) console.error(error);
    }
  },

  getLogs: async (): Promise<EntryLog[]> => {
    const { data, error } = await supabase.from('entry_logs').select('*');
    if (error) throw error;
    return (data || []).map(l => ({
      id: l.id,
      issuedPassId: l.pass_id,
      entryTime: l.entry_time,
      verifiedBy: l.verified_by
    }));
  },

  saveLogs: async (logs: EntryLog[]) => {
    for (const l of logs) {
      const { error } = await supabase.from('entry_logs').upsert({
        id: l.id,
        pass_id: l.issuedPassId,
        entry_time: l.entryTime,
        verified_by: l.verifiedBy
