import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { User, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Hospital as HospitalIcon, ArrowRight, Zap, Loader2 } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';
import { supabase } from './supabaseClient';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }

    const automationInterval = setInterval(async () => {
      const now = new Date();
      const today = now.toLocaleDateString('en-CA');
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      const currentTimeNum = now.getHours() * 100 + now.getMinutes();

      const hospitals = await storageService.getHospitals();

      // 1. Handle Automatic Pass Expiration
      const allPasses = await storageService.getPasses();
      let hasPassChanges = false;
      const updatedPasses = allPasses.map(p => {
        if (p.passDate === today && p.entryStatus !== 'expired') {
          let shouldExpire = false;
          if (p.session === 'MORNING' && currentTimeNum >= 1300) shouldExpire = true;
          if (p.session === 'EVENING' && currentTimeNum >= 2000) shouldExpire = true;
          if (p.session === 'FULL_DAY' && currentTimeNum >= 2000) shouldExpire = true;
          if (shouldExpire) {
            hasPassChanges = true;
            return { ...p, entryStatus: 'expired' as const };
          }
        }
        return p;
      });

      if (hasPassChanges) {
        await storageService.savePasses(updatedPasses);
      }

      // 2. Handle Automatic Lottery Triggering
      hospitals.forEach(async hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(async sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = await lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
              } else {
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 60000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = async (e?: React.FormEvent) => {
    e?.preventDefault();
    setIsLoggingIn(true);

    try {
      if (role === 'MR') {
        // Medical Representatives usually log in via their profile linked to mrs table
        const { data, error } = await supabase
          .from('profiles')
          .select('*, mrs(*, pharma_companies(name))')
          .eq('mobile_number', mobile)
          .eq('password', password)
          .eq('role', 'MR')
          .single();

        if (data) {
          const u: AuthUser = { 
            id: data.id, 
            fullName: data.full_name, 
            role: 'MR', 
            loginId: data.mobile_number,
            mobileNumber: data.mobile_number,
            companyName: (data.mrs as any)?.pharma_companies?.name || 'Pharma'
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Welcome back, ${u.fullName}!`);
        } else {
          showFeedback("Invalid MR credentials.", 'error');
        }
      } else {
        // Logic for ADMIN, SECURITY, COMPANY, and SUPER_ADMIN
        // Maps Frontend Role to Backend Role
        let dbRole: string = role;
        if (role === 'ADMIN') dbRole = 'HOSPITAL_ADMIN';
        if (role === 'COMPANY_ADMIN') dbRole = 'COMPANY';

        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('role', dbRole)
          .eq('password', password)
          // Look up by mobile_number OR full_name (for Super Admin who might use their name as ID)
          .or(`mobile_number.eq.${mobile},full_name.eq.${mobile}`)
          .single();

        if (data) {
          const u: AuthUser = { 
            id: data.id,
            role: role, 
            fullName: data.full_name, 
            hospitalId: data.hospital_id,
            mobileNumber: data.mobile_number,
            companyId: data.role === 'COMPANY' ? data.id : undefined // Simplified mapping
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${data.full_name}`);
        } else {
          showFeedback(`Invalid ${role} credentials.`, 'error');
        }
      }
    } catch (err) {
      showFeedback("Authentication failed. Please check connection and try again.", 'error');
    } finally {
      setIsLoggingIn(false);
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">Live Production Access</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'SUPER_ADMIN', '123456')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center col-span-2 hover:bg-slate-900 transition-all">
                     <Crown className="h-3 w-3 mb-1" /> Login as Root Authority (DB)
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Mobile Number' : 'Login ID / Identity'}</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "077xxxxxxx" : role === 'SUPER_ADMIN' ? "Identity Name" : "Login ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button 
                  type="submit" 
                  disabled={isLoggingIn}
                  className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-70"
                >
                  {isLoggingIn ? <Loader2 className="h-5 w-5 animate-spin" /> : <>Access Secure System <ArrowRight className="h-5 w-5" /></>}
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30 hover:grayscale-0 hover:opacity-100 transition-all cursor-default group">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-slate-900 backdrop-blur-md px-4 py-2 rounded-2xl border border-white/20 shadow-xl group-hover:border-indigo-400 transition-all">
                <Zap className="h-4 w-4 text-indigo-400" />
                <span className="text-sm font-black text-white tracking-tighter lowercase">dren</span>
              </div>
            </div>
            <p className="text-[9px] font-bold text-indigo-200 uppercase tracking-widest opacity-60">Professional Field Intelligence 3.0</p>
          </div>

          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user!} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user?.role === 'SUPER_ADMIN' ? 'Root Authority Control' : user?.role === 'MR' ? 'MR Dashboard' : `${user?.fullName} Management`}
      >
        {user?.role === 'MR' && <MRDashboard user={user as any} />}
        {user?.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user?.role === 'ADMIN' && <AdminDashboard user={user as any} />}
        {user?.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user?.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

