import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, HospitalUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);

  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [showPasswords, setShowPasswords] = useState(false);

  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    setHospitals(await storageService.getHospitals());
    setCompanies(await storageService.getCompanies());
    setMrs(await storageService.getMRs());
    setApps(await storageService.getApplications());
    setPasses(await storageService.getPasses());
  };

  const handleSaveHospital = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    // Generate valid UUID for the hospital
    const hospitalId = editingHospital.id || crypto.randomUUID();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      address: editingHospital.address || '',
      email: editingHospital.email || '',
      mobileNumber: editingHospital.mobileNumber || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      passLimits: editingHospital.passLimits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      sessionWindows: editingHospital.sessionWindows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    await storageService.saveHospitals([hospitalData]);

    const hospitalUsers = await storageService.getHospitalUsers();
    // Use existing UUIDs if editing, or new ones if creating
    const adminId = hospitalUsers.find(u => u.hospitalId === hospitalId && u.role === 'ADMIN')?.id || crypto.randomUUID();
    const securityId = hospitalUsers.find(u => u.hospitalId === hospitalId && u.role === 'SECURITY')?.id || crypto.randomUUID();

    const u: HospitalUser[] = [
      { id: adminId, hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password },
      { id: securityId, hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }
    ];

    await storageService.saveHospitalUsers(u);

    refreshData();
    setIsHospitalModalOpen(false);
    showFeedback("Hospital infrastructure provisioned.");
  };

  const handleSaveCompany = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) return;

    const companyId = editingCompany.id || crypto.randomUUID();
    const companyData: PharmaCompany = {
      id: companyId,
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      address: editingCompany.address || '',
      contactNumber: editingCompany.contactNumber || '',
      financeEmail: editingCompany.financeEmail || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    await storageService.saveCompanies([companyData]);
    refreshData();
    setIsCompanyModalOpen(false);
    showFeedback(`Partner ${companyData.name} registered.`);
  };

  const startEditHospital = async (h: Hospital) => {
    setEditingHospital(h);
    const users = (await storageService.getHospitalUsers()).filter(u => u.hospitalId === h.id);
    const admin = users.find(u => u.role === 'ADMIN');
    const security = users.find(u => u.role === 'SECURITY');

    setAdminData({ fullName: admin?.fullName || '', mobileNumber: admin?.mobileNumber || '', password: admin?.password || '' });
    setSecurityData({ fullName: security?.fullName || '', mobileNumber: security?.mobileNumber || '', password: security?.password || '' });
    setIsHospitalModalOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 ${activeTab === 'companies' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Briefcase className="h-4 w-4" /> Companies</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Facility Management</h3>
            <button onClick={() => { setEditingHospital({ isActive: true }); setIsHospitalModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg"><Plus className="h-4 w-4" /> PROVISION</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <h4 className="font-black text-slate-800 text-lg mb-1">{h.name}</h4>
                <p className="text-[10px] text-slate-400 font-bold mb-4">{h.email}</p>
                <button onClick={() => startEditHospital(h)} className="w-full py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl text-xs font-black">CONFIGURE</button>
              </div>
            ))}
          </div>
        </section>
      )}

      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl p-8">
            <h3 className="text-xl font-bold mb-6">Facility Setup</h3>
            <form onSubmit={handleSaveHospital} className="space-y-4">
              <input required type="text" value={editingHospital?.name || ''} onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" placeholder="Hospital Name" />
              <div className="p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 space-y-3">
                <p className="text-xs font-black text-indigo-900 uppercase">Admin Account</p>
                <input required type="text" value={adminData.fullName} onChange={e => setAdminData({...adminData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border rounded text-xs font-bold" placeholder="Admin Name" />
                <input required type="text" value={adminData.mobileNumber} onChange={e => setAdminData({...adminData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border rounded text-xs font-bold" placeholder="Admin Login ID" />
                <input required type="password" value={adminData.password} onChange={e => setAdminData({...adminData, password: e.target.value})} className="w-full px-3 py-2 bg-white border rounded text-xs font-bold" placeholder="Admin Password" />
              </div>
              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-3">
                <p className="text-xs font-black text-slate-800 uppercase">Security Account</p>
                <input required type="text" value={securityData.fullName} onChange={e => setSecurityData({...securityData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border rounded text-xs font-bold" placeholder="Security Name" />
                <input required type="text" value={securityData.mobileNumber} onChange={e => setSecurityData({...securityData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border rounded text-xs font-bold" placeholder="Security Login ID" />
                <input required type="password" value={securityData.password} onChange={e => setSecurityData({...securityData, password: e.target.value})} className="w-full px-3 py-2 bg-white border rounded text-xs font-bold" placeholder="Security Password" />
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={() => setIsHospitalModalOpen(false)} className="flex-1 py-4 bg-slate-100 font-black rounded-2xl text-xs">CANCEL</button>
                <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase text-xs">PROVISION</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Partner Management</h3>
            <button onClick={() => { setEditingCompany({ isActive: true }); setIsCompanyModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg"><Plus className="h-4 w-4" /> NEW PARTNER</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {companies.map(c => (
              <div key={c.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <h4 className="font-black text-slate-800 text-lg mb-1">{c.name}</h4>
                <p className="text-[10px] text-indigo-600 font-bold uppercase tracking-widest">{c.companyCode}</p>
                <button onClick={() => { setEditingCompany(c); setIsCompanyModalOpen(true); }} className="w-full mt-4 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl text-xs font-black">EDIT DETAILS</button>
              </div>
            ))}
          </div>
        </section>
      )}

      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl p-8">
            <h3 className="text-xl font-bold mb-6">Partner Registration</h3>
            <form onSubmit={handleSaveCompany} className="space-y-4">
              <input required type="text" value={editingCompany?.name || ''} onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" placeholder="Company Name" />
              <input required type="text" value={editingCompany?.companyCode || ''} onChange={e => setEditingCompany({...editingCompany, companyCode: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" placeholder="Company Code" />
              <input required type="text" value={editingCompany?.adminMobile || ''} onChange={e => setEditingCompany({...editingCompany, adminMobile: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" placeholder="Admin Mobile / Login" />
              <input required type="password" value={editingCompany?.adminPassword || ''} onChange={e => setEditingCompany({...editingCompany, adminPassword: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" placeholder="Admin Password" />
              <div className="flex gap-2">
                <button type="button" onClick={() => setIsCompanyModalOpen(false)} className="flex-1 py-4 bg-slate-100 font-black rounded-2xl text-xs">CANCEL</button>
                <button type="submit" className="flex-[2] bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase text-xs">REGISTER</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminDashboard;

import { supabase } from '../supabaseClient';
import { Hospital, HospitalUser } from '../types';

export const HospitalService = {
  getHospitals: async (): Promise<Hospital[]> => {
    const { data, error } = await supabase.from('hospitals').select('*');
    if (error) throw error;
    return (data || []).map(h => ({
      id: h.id,
      name: h.name,
      address: h.address,
      email: h.email,
      mobileNumber: h.mobile_number,
      isActive: h.is_active,
      supportedSessions: h.supported_sessions,
      passLimits: h.pass_limits,
      sessionWindows: h.session_windows,
      autoLotteryEnabled: h.auto_lottery_enabled,
      autoLotteryTimes: h.auto_lottery_times
    }));
  },

  saveHospitals: async (hospitals: Hospital[]) => {
    for (const h of hospitals) {
      const { error } = await supabase.from('hospitals').upsert({
        id: h.id,
        name: h.name,
        address: h.address,
        email: h.email,
        mobile_number: h.mobileNumber,
        is_active: h.isActive,
        supported_sessions: h.supportedSessions,
        pass_limits: h.passLimits,
        session_windows: h.sessionWindows,
        auto_lottery_enabled: h.autoLotteryEnabled,
        auto_lottery_times: h.autoLotteryTimes
      });
      if (error) {
        console.error("Save Hospital Error:", error);
        throw error;
      }
    }
  },

  getHospitalUsers: async (): Promise<HospitalUser[]> => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .in('role', ['HOSPITAL_ADMIN', 'SECURITY']);
    if (error) throw error;
    return (data || []).map(u => ({
      id: u.id,
      hospitalId: u.hospital_id,
      mobileNumber: u.mobile_number,
      password: u.password,
      role: u.role === 'HOSPITAL_ADMIN' ? 'ADMIN' : u.role as any,
      fullName: u.full_name
    }));
  },

  saveHospitalUsers: async (users: HospitalUser[]) => {
    for (const u of users) {
      const { error } = await supabase.from('profiles').upsert({
        id: u.id,
        hospital_id: u.hospitalId,
        mobile_number: u.mobileNumber,
        password: u.password,
        role: u.role === 'ADMIN' ? 'HOSPITAL_ADMIN' : u.role,
        full_name: u.fullName
      });
      if (error) {
        console.error("Save Profile Error:", error);
        throw error;
      }
    }
  },
};

import { supabase } from '../supabaseClient';
import { PharmaCompany } from '../types';

export const CompanyService = {
  getCompanies: async (): Promise<PharmaCompany[]> => {
    const { data, error } = await supabase.from('pharma_companies').select('*');
    if (error) throw error;

    // Get company admin profile data
    const { data: profiles } = await supabase.from('profiles').select('*').eq('role', 'COMPANY');
    const profileMap = new Map((profiles || []).map(p => [p.mobile_number, p]));

    return (data || []).map(c => {
      // Find the admin profile by mobile if possible, or leave blank
      const admin = profiles?.find(p => p.full_name.includes(c.name)) || null;
      return {
        id: c.id,
        name: c.name,
        companyCode: c.company_code,
        address: c.address,
        contactNumber: c.contact_number,
        financeEmail: c.finance_email,
        contactEmail: c.contact_email,
        isActive: c.is_active,
        adminMobile: admin?.mobile_number || '', 
        adminPassword: admin?.password || ''
      };
    });
  },

  saveCompanies: async (companies: PharmaCompany[]) => {
    for (const c of companies) {
      // 1. Save company to pharma_companies table
      const { error: companyErr } = await supabase.from('pharma_companies').upsert({
        id: c.id,
        name: c.name,
        company_code: c.companyCode,
        address: c.address,
        contact_number: c.contactNumber,
        finance_email: c.financeEmail,
        contact_email: c.contactEmail,
        is_active: c.isActive
      });
      if (companyErr) throw companyErr;

      // 2. Save company admin to profiles table
      if (c.adminMobile) {
        // Find existing profile for this company to preserve ID
        const { data: existing } = await supabase.from('profiles').select('id').eq('mobile_number', c.adminMobile).single();
        const profileId = existing?.id || crypto.randomUUID();

        const { error: profileErr } = await supabase.from('profiles').upsert({
          id: profileId,
          role: 'COMPANY',
          full_name: `${c.name} Administrator`,
          mobile_number: c.adminMobile,
          password: c.adminPassword
        });
        if (profileErr) console.error("Profile save error:", profileErr);
      }
    }
  },
};

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  UserPlus, Search, Briefcase, Mail, Phone, CreditCard, X, Edit3, Trash2, Power, 
  User, ShieldCheck, Activity, Users, Plus, Key, BarChart3, Clock, CheckCircle2, 
  Image as ImageIcon, Upload, Calendar, MapPin, DollarSign, Save, Copy, Check, AlertCircle, ArrowRight
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PharmaCompany, AuthUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

interface CompanyAdminDashboardProps {
  user: AuthUser;
}

const CompanyAdminDashboard: React.FC<CompanyAdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [company, setCompany] = useState<PharmaCompany | null>(null);
  const [activeTab, setActiveTab] = useState<'staff' | 'profile'>('staff');
  const [isMRModalOpen, setIsMRModalOpen] = useState(false);
  const [editingMR, setEditingMR] = useState<Partial<MedicalRep> | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const allCompanies = await storageService.getCompanies();
    const myCompany = allCompanies.find(c => c.id === user.companyId);
    if (myCompany) {
      setCompany(myCompany);
      const allMRs = await storageService.getMRs();
      setMrs(allMRs.filter(m => m.companyName === myCompany.name));
    }
  };

  const handleSaveMR = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMR?.fullName || !editingMR?.mobileNumber || !company) return;

    setIsSaving(true);
    // Use valid UUID
    const mrId = editingMR.id || crypto.randomUUID();

    const mrData: MedicalRep = {
      id: mrId,
      fullName: editingMR.fullName,
      companyName: company.name,
      mrId: editingMR.mrId || `MR-${Math.floor(1000 + Math.random() * 9000)}`,
      loginId: editingMR.mobileNumber,
      mobileNumber: editingMR.mobileNumber,
      identificationNumber: editingMR.identificationNumber || '',
      status: (editingMR.status as any) || 'active',
      createdAt: editingMR.createdAt || new Date().toISOString()
    };

    try {
      await storageService.saveMRs([mrData]);
      refreshData();
      setIsMRModalOpen(false);
      showFeedback(`Successfully saved ${mrData.fullName}`);
    } catch (err) {
      showFeedback("Failed to save representative. Check DB constraints.", "error");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('staff')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 ${activeTab === 'staff' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Users className="h-4 w-4" /> Staff</button>
      </div>

      {activeTab === 'staff' && (
        <section className="bg-white rounded-3xl border border-slate-100 shadow-sm p-8">
          <div className="flex justify-between items-center mb-8">
            <h3 className="font-black text-slate-800">Deployment Registry</h3>
            <button onClick={() => { setEditingMR({ status: 'active' }); setIsMRModalOpen(true); }} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg"><Plus className="h-4 w-4" /> ADD MR</button>
          </div>
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
             {mrs.map(m => (
               <div key={m.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="font-black text-slate-800">{m.fullName}</p>
                  <p className="text-[10px] text-indigo-600 font-bold">{m.mrId}</p>
               </div>
             ))}
          </div>
        </section>
      )}

      {isMRModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8">
            <h3 className="text-xl font-bold mb-6">MR Registration</h3>
            <form onSubmit={handleSaveMR} className="space-y-4">
              <input required type="text" value={editingMR?.fullName || ''} onChange={e => setEditingMR({...editingMR, fullName: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" placeholder="Full Name" />
              <input required type="text" value={editingMR?.mobileNumber || ''} onChange={e => setEditingMR({...editingMR, mobileNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" placeholder="Mobile / Login" />
              <button disabled={isSaving} type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase text-xs">REGISTER MR</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

