    const security = users.find(u => u.role === 'SECURITY');

    setAdminData({ 
      fullName: admin?.fullName || '', 
      mobileNumber: admin?.mobileNumber || '', 
      password: admin?.password || '' 
    });
    setSecurityData({ 
      fullName: security?.fullName || '', 
      mobileNumber: security?.mobileNumber || '', 
